// Legacy compatibility exports
export interface QuizPairMapping {
  id: string
  primary_dimension: number
  signal: number
  secondary_dimension?: number
  secondary_signal?: number
}

export interface QuizResponseWithDimension {
  pair_id: string
  chosen: 'A' | 'B'
  super_liked: boolean
}

export const QUIZ_PAIR_DIMENSIONS: Record<string, QuizPairMapping> = {}

export function computeFingerprintFromPairs(
  _responses: QuizResponseWithDimension[],
  _skipFirst = true
): number[] {
  return [0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5]
}
